package org.kanger;
import java.util.*;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextProductionCapture.*;
import org.kanger.ContextUniversalInputResiduals.Residual;
import org.kanger.ContextUniversalFrozenConstraints.*;
import org.kanger.ContextUniversalFrozenConstraints.Result;
import org.kanger.ContextWitnessResultTransport.*;

/** Whole witness rows and their actual carried proofs, never renamed variables or invented bindings. */
public final class ContextUniversalFrozenConstraintsRunner {
    static int checks;static final int WORK=64000000;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static Snapshot bind(boolean x,String s)throws Exception{return ContextPrivateWitnessPoolRunner.bind(x,s);}
    static ContextUniversalNativeRows.Result rows(Snapshot x,Snapshot a){ContextUniversalNativeRows.Result r=ContextUniversalNativeRows.inspect(x,a,64,WORK);require(r.classified,r.reason);return r;}
    static Result close(ContextUniversalNativeRows.Result r,Packet input,PrivatePool pool,int depth){return ContextUniversalFrozenConstraints.close(r,input,pool,16,depth,512,256,WORK);}
    static Result good(ContextUniversalNativeRows.Result rows,Packet common,PrivatePool pool,int depth){Result r=close(rows,common,pool,depth);require(r.closed,r.reason);require(r.input==rows&&r.common==common&&r.pool==pool&&r.local==(pool==null?common:pool.local),"actual whole native/common/private frame");ContextUniversalFrozenConstraints.check(r,depth,()->{});audit(r);return r;}
    static boolean same(Residual a,Residual b){return a==null?b==null:b!=null&&a.equivalent(b,()->{});}
    static void audit(Result r){Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Proof p:r.proofs)auditProof(p,r,seen);for(ContextUniversalNativeRows.Row row:r.input.rows)for(ContextUniversalNativeRows.Part part:row.parts)if(part.clause!=null)require(r.proofs.stream().anyMatch(p->p.support.depth==0&&p.support.sources.equals(Collections.singleton(row.original.source))&&same(p.clause,ContextUniversalInputResiduals.schema(part.clause,()->{}))),"every ordinary original root covered with whole Source0");for(Item item:r.local.items)for(Support support:item.proofs)require(r.proofs.stream().anyMatch(p->p.support.sources.equals(support.sources)&&p.support.depth<=support.depth&&same(p.clause,ContextUniversalInputResiduals.fact(item,()->{}))),"every carried Item/Support covered without resetting depth");}
    static void auditProof(Proof p,Result r,Set<Proof> seen){if(!seen.add(p))return;if(p.original!=null){require(r.input.rows.contains(p.original)&&p.original.parts.contains(p.part),"actual native Row/Part objects");require(same(p.clause,ContextUniversalInputResiduals.schema(p.part.clause,()->{}))&&p.support.depth==0&&p.support.sources.equals(Collections.singleton(p.original.original.source)),"whole original root shape/Source/grade");}else if(p.input!=null){require(r.local.items.stream().anyMatch(i->i==p.input)&&p.input.proofs.contains(p.inputProof)&&p.support.equals(p.inputProof),"actual owning Item/Support reference");require(same(p.clause,ContextUniversalInputResiduals.fact(p.input,()->{})),"carried fact rigid Origins unchanged");}else{auditProof(p.unit,r,seen);auditProof(p.horn,r,seen);Residual expected=ContextUniversalInputResiduals.resolveConstraint(p.unit.clause,p.horn.clause,p.pivot,()->{});require(same(expected,p.clause),"principal typed resolvent including empty");Set<Source> sources=new HashSet<>(p.unit.support.sources);sources.addAll(p.horn.support.sources);require(p.support.sources.equals(sources)&&p.support.depth==Math.max(p.unit.support.depth,p.horn.support.depth)+1,"whole actual parent Sources and cumulative grade");}}
    static void no(Result r,String why){require(!r.closed&&!r.xRefuted&&!r.foreignRefuted&&r.proofs.isEmpty()&&r.emptyProofs.isEmpty(),why+": "+r.reason);}
    static void witnessIdentity()throws Exception {
        String together="!$w seed(w,1)&&flag(w,1);",negative="!@w seed(w,1)->~flag(w,1);";
        Snapshot x=bind(true,together),a=bind(false,negative);Packet common=ContextPrivateWitnessPoolRunner.common(x);Result r=good(rows(x,a),common,null,2);
        require(r.xRefuted&&!r.foreignRefuted&&r.emptyProofs.size()==1,"one shared original binder proves sourced contradiction");require(r.emptyProofs.get(0).support.sources.equals(new HashSet<>(Arrays.asList(x.primary.get(0).source,a.primary.get(0).source)))&&r.emptyProofs.get(0).support.depth==2,"whole bundle Source and negative rule Source at empty2");
        Snapshot split=bind(true,"!$w seed(w,1); !$w flag(w,1);");Packet distinct=ContextPrivateWitnessPoolRunner.common(split);Result independent=good(rows(split,a),distinct,null,2);require(!independent.xRefuted&&independent.emptyProofs.isEmpty(),"same binder index/name in separate original Sources cannot alias");require(independent.proofs.stream().filter(p->p.clause!=null).flatMap(p->p.clause.origins.stream()).distinct().count()==2,"both rigid original Origins retained, no inequality fact invented");
        no(close(rows(x,a),common,null,1),"bounded missing empty2 exposes no earlier successful proof prefix");
        Snapshot pair=bind(true,"!$u $v pair(u,v);"),forbid=bind(false,"!@u @v ~pair(u,v);");Packet two=ContextPrivateWitnessPoolRunner.common(pair);Result all=good(rows(pair,forbid),two,null,1);require(all.xRefuted&&all.emptyProofs.get(0).support.depth==1,"two original binders in one carried literal remain available to universal refutation");
        Snapshot reverse=bind(false,"!@u @v pair(u,v)->~pair(v,u);");Result directed=good(rows(pair,reverse),two,null,16);require(!directed.xRefuted,"distinct physical binders are not silently equated by reversal");
        no(close(rows(x,a),ContextPrivateWitnessPoolRunner.common(split),null,16),"another X cut cannot own these raw witness proofs");
        require(common.items.size()==2&&r.local==common,"no new Packet or common mutation");
    }
    static void privateFrames()throws Exception {
        String negative="!@w seed(w,1)->~flag(w,1);";Snapshot x=bind(true,"!anchor(1); "+negative),a=bind(false,"!$w seed(w,1)&&flag(w,1);");Packet common=ContextPrivateWitnessPoolRunner.common(x);PrivatePool pool=ContextWitnessResultTransport.privatePool(common,x,a,WORK);ContextUniversalNativeRows.Result inventory=rows(x,a);Result r=good(inventory,common,pool,2);require(r.xRefuted&&r.emptyProofs.stream().allMatch(p->p.support.sources.equals(new HashSet<>(Arrays.asList(ContextPrivateWitnessPoolRunner.source(x,negative),a.primary.get(0).source)))) ,"negative X rule participates, unrelated X anchor absent");
        no(close(inventory,common,null,16),"missing private whole witness row refuses rather than a partial no-collision result");
        no(close(inventory,ContextPrivateWitnessPoolRunner.common(x),pool,16),"equal common contents cannot replace actual private frame");
        Snapshot equal=bind(false,"!$w seed(w,1)&&flag(w,1);");no(close(rows(x,equal),common,pool,16),"equal formulas cannot replace private native snapshot/physical Origin");
        Snapshot anchor=bind(true,"!anchor(1);"),rule=bind(false,negative);Snapshot group=ContextProductionNativeBinding.trusted("own",Arrays.asList(a,rule),WORK);Packet base=ContextPrivateWitnessPoolRunner.common(anchor);PrivatePool privateOnly=ContextWitnessResultTransport.privatePool(base,anchor,group,WORK);Result local=good(rows(anchor,group),base,privateOnly,2);require(local.foreignRefuted&&!local.xRefuted,"private-only refutation retained without unrelated X dependence");
        for(Proof p:local.emptyProofs)require(p.support.sources.stream().noneMatch(s->s.localX),"physical private Source history only");
        Snapshot independent=bind(false,"!$w seed(w,1); !$w flag(w,1);");PrivatePool split=ContextWitnessResultTransport.privatePool(common,x,independent,WORK);require(!good(rows(x,independent),common,split,16).xRefuted,"independent private witnesses stay independent inside one cut");
        require(pool.common==common&&common.items.stream().noneMatch(i->i.atom.predicate.equals("seed")),"raw private input never shared or modified");
    }
    static void ordinaryAndCarriedDepth()throws Exception {
        Snapshot x=bind(true,"!p(1);"),a=bind(false,"!@u p(u)->q(u); !~q(1);");Packet input=ContextPrivateWitnessPoolRunner.common(x);Result r=good(rows(x,a),input,null,2);require(r.xRefuted&&r.emptyProofs.get(0).support.sources.size()==3,"ordinary whole-ledger producer/constraint behavior preserved");
        Snapshot negativeX=bind(true,"!anchor(1); !~q(1);"),positiveA=bind(false,"!q(1);");Packet signed=ContextPrivateWitnessPoolRunner.common(negativeX);Result opposite=good(rows(negativeX,positiveA),signed,null,1);require(opposite.xRefuted&&signed.items.stream().anyMatch(i->!i.atom.positive),"negative ordinary common fact remains a constraint, positive foreign native unit is not omitted");
        Snapshot universalX=bind(true,"!anchor(1); !@u p(u);"),universalA=bind(false,"!@v ~p(v);");require(good(rows(universalX,universalA),ContextPrivateWitnessPoolRunner.common(universalX),null,1).xRefuted,"universals still refute without observed-value enumeration");
        Snapshot px=bind(true,"!$w seed(w,1);"),producer=bind(false,"!@w seed(w,1)->mid(w,1);");Packet common=ContextPrivateWitnessPoolRunner.common(px);ContextUniversalFrozenBranch.Result produced=ContextUniversalFrozenBranch.run(px,producer,common,ContextUniversalFrozenBranchRunner.full());require(produced.produced,produced.reason);Packet carried=produced.products.transfer.output;
        Snapshot constraint=bind(false,"!@w ~mid(w,1);");Result later=good(rows(px,constraint),carried,null,2);require(later.xRefuted&&later.emptyProofs.get(0).support.depth==2&&later.emptyProofs.get(0).support.sources.size()==3,"historical carried product retains producer/binding Sources and depth1 before refutation+1");
        require(later.proofs.stream().anyMatch(p->p.input!=null&&p.input.atom.predicate.equals("mid")&&p.support.depth==1),"actual carried product Item/Support imported without depth reset");
        Snapshot ordinary=bind(false,"!~seed(7,1);");require(!good(rows(px,ordinary),common,null,16).xRefuted,"rigid witness is not an arbitrary ordinary value");
        Residual positive=ContextUniversalInputResiduals.schema(bind(false,"!p(1);").primary.get(0).clauses.get(0),()->{}),negative=ContextUniversalInputResiduals.schema(bind(false,"!~p(1);").primary.get(0).clauses.get(0),()->{});
        require(ContextUniversalInputResiduals.resolveConstraint(positive,negative,0,()->{})==null,"empty only returned by explicit constraint resolver");try{ContextUniversalInputResiduals.resolve(positive,negative,0,()->{});throw new AssertionError();}catch(IllegalStateException expected){++checks;}
    }
    static void boundsAndWholeRows()throws Exception {
        Snapshot x=bind(true,"!$w seed(w,1)&&flag(w,1);"),a=bind(false,"!@w seed(w,1)->~flag(w,1);");Packet common=ContextPrivateWitnessPoolRunner.common(x);ContextUniversalNativeRows.Result inventory=rows(x,a);
        no(ContextUniversalFrozenConstraints.close(inventory,common,null,1,16,512,256,WORK),"round limit no partial refutation");no(ContextUniversalFrozenConstraints.close(inventory,common,null,16,16,1,256,WORK),"clause limit no partial roots");no(ContextUniversalFrozenConstraints.close(inventory,common,null,16,16,512,256,1),"work limit no prefix");
        Snapshot signed=bind(false,"!$w seed(w,1)&&~flag(w,1);");no(close(rows(x,signed),common,null,16),"unsupported signed row not dropped");Snapshot disjunction=bind(false,"!a(1)||b(1);");no(close(rows(x,disjunction),common,null,16),"unsupported ordinary row not dropped");
        Snapshot group=ContextProductionNativeBinding.trusted("own",Arrays.asList(a,bind(false,"!$w extra(w);")),WORK);no(close(rows(x,group),common,null,16),"later unavailable original witness row cannot leave earlier contradiction prefix");
        no(close(null,common,null,16),"actual native ledger required");try{ContextUniversalFrozenConstraints.close(inventory,common,null,0,16,512,256,WORK);throw new AssertionError();}catch(IllegalArgumentException expected){++checks;}
        Result r=good(inventory,common,null,2);try{r.proofs.clear();throw new AssertionError();}catch(UnsupportedOperationException expected){++checks;}try{r.emptyProofs.clear();throw new AssertionError();}catch(UnsupportedOperationException expected){++checks;}
    }
    static void alternativesAndMinima()throws Exception {
        Snapshot x=bind(true,"!$w p(w,1);"),a=bind(false,"!@w ~p(w,1);"),loop=bind(false,"!@w p(w,1)->p(w,1);");Packet common=ContextPrivateWitnessPoolRunner.common(x);Snapshot group=ContextProductionNativeBinding.trusted("own",Arrays.asList(a,loop),WORK);ContextUniversalNativeRows.Result inventory=rows(x,group);Result r=good(inventory,common,null,2);
        require(r.emptyProofs.stream().anyMatch(p->p.support.sources.size()==2&&p.support.depth==1)&&r.emptyProofs.stream().anyMatch(p->p.support.sources.size()==3&&p.support.depth==2),"rigid-Origin refutations retain deeper Source superset alongside smaller proof");
        no(close(inventory,common,null,1),"deeper exact Source alternative cannot hide behind shorter different-Source empty proof");
        no(ContextUniversalFrozenConstraints.close(inventory,common,null,16,16,512,1,WORK),"Source alternative cap hides all earlier partial proofs");
        Snapshot reverse=ContextProductionNativeBinding.trusted("own",Arrays.asList(loop,a),WORK);Result back=good(rows(x,reverse),common,null,2);Set<Support> before=new HashSet<>(),after=new HashSet<>();for(Proof p:r.emptyProofs)before.add(p.support);for(Proof p:back.emptyProofs)after.add(p.support);require(before.equals(after),"trusted member order preserves every empty Source alternative/minimum");
        Snapshot both=bind(true,"!$w p(w,1)&&q(w,1);"),mixed=bind(false,"!@w (p(w,1)->q(w,1))&&~q(w,1);");Result minimum=good(rows(both,mixed),ContextPrivateWitnessPoolRunner.common(both),null,1);require(minimum.emptyProofs.stream().allMatch(p->p.support.depth==1),"shorter exact-Source empty proof covers deeper rigid-Origin recipe before depth decision");
        Snapshot apart=bind(true,"!anchor(1); !@u p(u,1);"),negative=bind(false,"!@u ~p(2,u);");require(good(rows(apart,negative),ContextPrivateWitnessPoolRunner.common(apart),null,1).xRefuted,"typed empty resolver standardizes independent equal variable IDs apart");
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("frozen-constraints-").toString());witnessIdentity();privateFrames();ordinaryAndCarriedDepth();boundsAndWholeRows();alternativesAndMinima();System.out.println("CONTEXT_UNIVERSAL_FROZEN_CONSTRAINTS_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
